  "basic": "'use client';\n\nimport React from 'react';\nimport { Select, Space } from '@ceebee/ui/client';\n\nconst handleChange = (value: string) => {\n  console.log(`selected ${value}`);\n};\n\nconst App: React.FC = () => (\n  <Space wrap>\n    <Select\n      defaultValue=\"lucy\"\n      style={{ width: 120 }}\n      onChange={handleChange}\n      options={[\n        { value: 'jack', label: 'Jack' },\n        { value: 'lucy', label: 'Lucy' },\n        { value: 'Yiminghe', label: 'yiminghe' },\n        { value: 'disabled', label: 'Disabled', disabled: true },\n      ]}\n    />\n    <Select\n      defaultValue=\"lucy\"\n      style={{ width: 120 }}\n      disabled\n      options={[{ value: 'lucy', label: 'Lucy' }]}\n    />\n    <Select\n      defaultValue=\"lucy\"\n      style={{ width: 120 }}\n      loading\n      options={[{ value: 'lucy', label: 'Lucy' }]}\n    />\n    <Select\n      defaultValue=\"lucy\"\n      style={{ width: 120 }}\n      allowClear\n      options={[{ value: 'lucy', label: 'Lucy' }]}\n      placeholder=\"select it\"\n    />\n  </Space>\n);\n\nexport default App;\n",
  "big-data": "'use client';\n\nimport React from 'react';\nimport type { SelectProps } from '@ceebee/ui/client';\nimport { Select, Typography } from '@ceebee/ui/client';\n\nconst { Title } = Typography;\n\nconst options: SelectProps['options'] = [];\n\nfor (let i = 0; i < 100000; i++) {\n  const value = `${i.toString(36)}${i}`;\n  options.push({\n    label: value,\n    value,\n    disabled: i === 10,\n  });\n}\n\nconst handleChange = (value: string[]) => {\n  console.log(`selected ${value}`);\n};\n\nconst App: React.FC = () => (\n  <>\n    <Title level={4}>{options.length} Items</Title>\n    <Select\n      mode=\"multiple\"\n      style={{ width: '100%' }}\n      placeholder=\"Please select\"\n      defaultValue={['a10', 'c12']}\n      onChange={handleChange}\n      options={options}\n    />\n  </>\n);\n\nexport default App;\n",
  "coordinate": "'use client';\n\nimport React, { useState } from 'react';\nimport { Select, Space } from '@ceebee/ui/client';\n\nconst cityData = {\n  Zhejiang: ['Hangzhou', 'Ningbo', 'Wenzhou'],\n  Jiangsu: ['Nanjing', 'Suzhou', 'Zhenjiang'],\n};\n\ntype CityName = keyof typeof cityData;\n\nconst provinceData: CityName[] = ['Zhejiang', 'Jiangsu'];\n\nconst App: React.FC = () => {\n  const [cities, setCities] = useState(cityData[provinceData[0] as CityName]);\n  const [secondCity, setSecondCity] = useState(cityData[provinceData[0] as CityName][0] as CityName);\n\n  const handleProvinceChange = (value: CityName) => {\n    setCities(cityData[value]);\n    setSecondCity(cityData[value][0] as CityName);\n  };\n\n  const onSecondCityChange = (value: CityName) => {\n    setSecondCity(value);\n  };\n\n  return (\n    <Space wrap>\n      <Select\n        defaultValue={provinceData[0]}\n        style={{ width: 120 }}\n        onChange={handleProvinceChange}\n        options={provinceData.map((province) => ({ label: province, value: province }))}\n      />\n      <Select\n        style={{ width: 120 }}\n        value={secondCity}\n        onChange={onSecondCityChange}\n        options={cities.map((city) => ({ label: city, value: city }))}\n      />\n    </Space>\n  );\n};\n\nexport default App;\n",
  "custom-dropdown-menu": "'use client';\n\nimport React, { useRef, useState } from 'react';\nimport { PlusOutlined } from '@ant-design/icons';\nimport { Button, Divider, Input, Select, Space } from '@ceebee/ui/client';\nimport type { InputRef } from '@ceebee/ui/client';\n\nlet index = 0;\n\nconst App: React.FC = () => {\n  const [items, setItems] = useState(['jack', 'lucy']);\n  const [name, setName] = useState('');\n  const inputRef = useRef<InputRef>(null);\n\n  const onNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {\n    setName(event.target.value);\n  };\n\n  const addItem = (e: React.MouseEvent<HTMLButtonElement | HTMLAnchorElement>) => {\n    e.preventDefault();\n    setItems([...items, name || `New item ${index++}`]);\n    setName('');\n    setTimeout(() => {\n      inputRef.current?.focus();\n    }, 0);\n  };\n\n  return (\n    <Select\n      style={{ width: 300 }}\n      placeholder=\"custom dropdown render\"\n      popupRender={(menu) => (\n        <>\n          {menu}\n          <Divider style={{ margin: '8px 0' }} />\n          <Space style={{ padding: '0 8px 4px' }}>\n            <Input\n              placeholder=\"Please enter item\"\n              ref={inputRef}\n              value={name}\n              onChange={onNameChange}\n              onKeyDown={(e) => e.stopPropagation()}\n            />\n            <Button type=\"text\" icon={<PlusOutlined />} onClick={addItem}>\n              Add item\n            </Button>\n          </Space>\n        </>\n      )}\n      options={items.map((item) => ({ label: item, value: item }))}\n    />\n  );\n};\n\nexport default App;\n",
  "custom-label-render": "'use client';\n\nimport React from 'react';\nimport { Select } from '@ceebee/ui/client';\nimport type { SelectProps } from '@ceebee/ui/client';\n\ntype LabelRender = SelectProps['labelRender'];\n\nconst options = [\n  { label: 'gold', value: 'gold' },\n  { label: 'lime', value: 'lime' },\n  { label: 'green', value: 'green' },\n  { label: 'cyan', value: 'cyan' },\n];\n\nconst labelRender: LabelRender = (props) => {\n  const { label, value } = props;\n\n  if (label) {\n    return value;\n  }\n  return <span>No option match</span>;\n};\n\nconst App: React.FC = () => (\n  <Select labelRender={labelRender} defaultValue=\"1\" style={{ width: '100%' }} options={options} />\n);\n\nexport default App;\n",
  "custom-tag-render": "'use client';\n\nimport React from 'react';\nimport { Select, Tag } from '@ceebee/ui/client';\nimport type { SelectProps } from '@ceebee/ui/client';\n\ntype TagRender = SelectProps['tagRender'];\n\nconst options: SelectProps['options'] = [\n  { value: 'gold' },\n  { value: 'lime' },\n  { value: 'green' },\n  { value: 'cyan' },\n];\n\nconst tagRender: TagRender = (props) => {\n  const { label, value, closable, onClose } = props;\n  const onPreventMouseDown = (event: React.MouseEvent<HTMLSpanElement>) => {\n    event.preventDefault();\n    event.stopPropagation();\n  };\n  return (\n    <Tag\n      color={value}\n      onMouseDown={onPreventMouseDown}\n      closable={closable}\n      onClose={onClose}\n      style={{ marginInlineEnd: 4 }}\n    >\n      {label}\n    </Tag>\n  );\n};\n\nconst App: React.FC = () => (\n  <Select\n    mode=\"multiple\"\n    tagRender={tagRender}\n    defaultValue={['gold', 'cyan']}\n    style={{ width: '100%' }}\n    options={options}\n  />\n);\n\nexport default App;\n",
  "custom-tokenization": "'use client';\n\nimport React from 'react';\nimport { Select } from '@ceebee/ui/client';\n\nconst tokenize = (input: string): string[] => {\n  const tokens: string[] = [];\n  const regex = /\"([^\"]*)\"|([^,\\n]+)/g;\n  let match: RegExpExecArray | null = regex.exec(input);\n  while (match) {\n    tokens.push((match[1] ?? match[2] ?? '').trim());\n    match = regex.exec(input);\n  }\n  return tokens.filter(Boolean);\n};\n\nconst App: React.FC = () => (\n  <Select\n    mode=\"tags\"\n    style={{ width: '100%' }}\n    tokenSeparators={tokenize}\n    placeholder='Try paste: \"San Francisco, CA\", New York'\n  />\n);\n\nexport default App;\n",
  "hide-selected": "'use client';\n\nimport React, { useState } from 'react';\nimport { Select } from '@ceebee/ui/client';\n\nconst OPTIONS = ['Apples', 'Nails', 'Bananas', 'Helicopters'];\n\nconst App: React.FC = () => {\n  const [selectedItems, setSelectedItems] = useState<string[]>([]);\n\n  const filteredOptions = OPTIONS.filter((o) => !selectedItems.includes(o));\n\n  return (\n    <Select\n      mode=\"multiple\"\n      placeholder=\"Inserted are removed\"\n      value={selectedItems}\n      onChange={setSelectedItems}\n      style={{ width: '100%' }}\n      options={filteredOptions.map((item) => ({\n        value: item,\n        label: item,\n      }))}\n    />\n  );\n};\n\nexport default App;\n",
